'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Sheet, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './sheet.css'

import { Button } from './button'
import { trapFocus } from './trap'

/**
 * Sheet: a surface that rises from the bottom of its container for one short
 * job, then goes.
 *
 * Specimen 5c draws it: a scrim over the scene, a panel anchored to the foot of
 * the container with a grab handle, a header row of art, kicker, title and a
 * line of body, whatever the host puts in the middle, then a primary action and
 * a ghost under it. It is for reward detail, the options of a select on touch,
 * share, filters and "more". Anything taller than sixty percent of its
 * container is a page rather than a sheet, and the panel is capped there.
 *
 * It is modal while open, which is the opposite of the coach mark rule and
 * deliberately so: focus is held inside the panel, Escape closes it, the scrim
 * closes it, and focus goes back to whatever had it. It is unmounted rather
 * than hidden when closed. A dismissed coach mark stays in the DOM carrying
 * `data-gs-dismissed` because the host may bring it back; a sheet that has
 * been dismissed is gone, and whether the player closed it is the host's
 * state, not the sheet's.
 *
 * It positions against the nearest positioned ancestor, so a host puts one
 * inside the surface it belongs to, the way a coach mark is placed. It
 * performs nothing: it decides nothing about what the actions do and holds no
 * state of its own beyond where focus was.
 */

export interface SheetAction {
  /** The verb of its outcome: Claim, Share, Apply. */
  label: string
  onClick: () => void
}

export interface SheetProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  /** Rendered when true, unmounted when false. */
  open: boolean
  /** Called on the scrim, on Escape and on the ghost action. */
  onDismiss: () => void
  /** The accessible name of the dialog. Required, because a dialog needs one. */
  label: string
  /** The heading in the header row, if the sheet has one. */
  title?: string
  /** The small line above the heading, in the warning colour: PRIZE, UNCLAIMED. */
  kicker?: string
  /** The 88px art beside the heading, supplied by the host. */
  media?: React.ReactNode
  /** The line under the heading. */
  description?: string
  /** The one thing the sheet is for. Rendered as the library's primary button. */
  primaryAction?: SheetAction
  /** The way out that is not the scrim. Rendered as a ghost; dismisses as well. */
  secondaryAction?: SheetAction
}

export function Sheet({
  open,
  onDismiss,
  label,
  title,
  kicker,
  media,
  description,
  primaryAction,
  secondaryAction,
  className,
  children,
  ...rest
}: SheetProps) {
  const panelRef = React.useRef<HTMLDivElement | null>(null)

  // The trap reads the latest handler through a ref so the effect runs once
  // per opening rather than once per render, which would move focus back to
  // the first control every time the host re-rendered.
  const dismissRef = React.useRef(onDismiss)
  dismissRef.current = onDismiss

  React.useEffect(() => {
    if (!open || !panelRef.current) return
    return trapFocus({ panel: panelRef.current, onEscape: () => dismissRef.current() })
  }, [open])

  if (!open) return null

  const header = title !== undefined || kicker !== undefined || media !== undefined || description !== undefined

  return (
    <div {...rest} className={['gs-sheet', className].filter(Boolean).join(' ')} data-gs-component="sheet">
      {/* A tap on the scrim dismisses. It is emphasis rather than motion: the
          scrim darkens, it does not move, so its fade survives reduced motion
          and is what remains of the entrance there. */}
      <div
        className="gs-sheet__scrim"
        data-gs-scope="sheet"
        data-gs-part="scrim"
        data-gs-motion="fade"
        data-gs-animates="emphasis"
        aria-hidden="true"
        onClick={onDismiss}
      />
      <div
        ref={panelRef}
        className="gs-sheet__panel"
        data-gs-scope="sheet"
        data-gs-part="panel"
        data-gs-motion="sheet"
        data-gs-animates="motion"
        role="dialog"
        aria-modal="true"
        aria-label={label}
        tabIndex={-1}
      >
        <span className="gs-sheet__thumb" data-gs-scope="sheet" data-gs-part="thumb" aria-hidden="true" />
        {header ? (
          <div className="gs-sheet__header">
            {media !== undefined ? (
              <div className="gs-sheet__media" data-gs-scope="sheet" data-gs-part="media">
                {media}
              </div>
            ) : null}
            <div className="gs-sheet__words">
              {kicker !== undefined ? (
                <span className="gs-sheet__note" data-gs-scope="sheet" data-gs-part="note">
                  {kicker}
                </span>
              ) : null}
              {title !== undefined ? (
                <span className="gs-sheet__label" data-gs-scope="sheet" data-gs-part="label">
                  {title}
                </span>
              ) : null}
              {description !== undefined ? (
                <span className="gs-sheet__body" data-gs-scope="sheet" data-gs-part="body">
                  {description}
                </span>
              ) : null}
            </div>
          </div>
        ) : null}
        {children !== undefined && children !== null ? <div className="gs-sheet__content">{children}</div> : null}
        {primaryAction || secondaryAction ? (
          <div className="gs-sheet__actions" data-gs-scope="sheet" data-gs-part="actions">
            {primaryAction ? (
              <Button variant="primary" data-gs-scope="sheet" data-gs-part="commit" onClick={primaryAction.onClick}>
                {primaryAction.label}
              </Button>
            ) : null}
            {secondaryAction ? (
              <Button
                variant="tertiary"
                data-gs-scope="sheet"
                data-gs-part="dismiss"
                onClick={() => {
                  secondaryAction.onClick()
                  onDismiss()
                }}
              >
                {secondaryAction.label}
              </Button>
            ) : null}
          </div>
        ) : null}
      </div>
    </div>
  )
}

/* Sheet. Every value comes from a token; nothing here is a literal colour.

   Specimen 5c draws this and design/twins/5c.json measures ours against it: a
   scrim over the scene, a surface panel anchored to the foot of the container
   with a 3px edge on its top and sides, 22px round at the top, padded 12 16
   24, a 48 by 5 grab handle in edge-high 14px below the top, then the header
   row, the content, a positive primary and a ghost. */

/* The root covers its container, so a host puts `position: relative` on the
   surface the sheet belongs to, as it does for a coach mark. Above the coach
   mark's 1: a sheet is in front of guidance. */
.gs-sheet {
  position: absolute;
  inset: 0;
  z-index: 2;
}

/* The drawing writes its scrim as a navy at 60% inline; ours is the scrim token, which is
   what every other darkened layer in the library reads. */
.gs-sheet__scrim {
  position: absolute;
  inset: 0;
  background: var(--gs-color-scrim);
}

.gs-sheet__panel {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  /* Sixty percent of the container. Taller content is a page, not a sheet; what
     does not fit scrolls inside the content region below. */
  max-height: 60%;
  display: flex;
  flex-direction: column;
  padding: var(--gs-space-3) var(--gs-space-4) var(--gs-space-6);

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink);

  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-bottom: 0;
  border-radius: var(--gs-radius-xl) var(--gs-radius-xl) 0 0;
  /* The drawing casts `inset 0 2px 0 edge-high, 0 -12px 40px shadow`: the
     raised highlight along the top and a soft drop upward on to the scene.
     No depth token is an upward drop. depth.raised carries the same highlight
     in arcade and puts its shelf below the sheet, where the container clips
     it; the upward drop is a token request, depth.sheet. */
  box-shadow: var(--gs-depth-raised);
  outline: none;
}

/* 48 by 5, 3px round, edge-high, centred, 14 below the top. space.12 is the
   48; the height is space.1, 4px, because 5px is not a length any token has;
   a pill radius on a 5px bar is the same shape as the drawing's 3px. */
.gs-sheet__thumb {
  flex: none;
  width: var(--gs-space-12);
  height: var(--gs-space-1);
  margin: 0 auto var(--gs-space-inset);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge-high-solid);
}

/* -- the header row -------------------------------------------------------- */
.gs-sheet__header {
  flex: none;
  display: flex;
  gap: var(--gs-space-inset);
  align-items: center;
  margin-bottom: var(--gs-space-4);
}

/* The art: 88px square, 16px round, 3px edge. No size token is 88;
   size.iconHero, 64, is the nearest and is what a hero-sized mark takes
   everywhere else. Token request size.media. Whatever the host puts in it
   fills it; a reward ring or glow is the host's reward state and not the
   sheet's. */
.gs-sheet__media {
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-icon-hero);
  height: var(--gs-size-icon-hero);
  overflow: hidden;
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
}

.gs-sheet__media > img,
.gs-sheet__media > picture,
.gs-sheet__media > video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gs-sheet__words {
  flex: 1;
  min-width: 0;
  display: grid;
}

/* PRIZE, UNCLAIMED: the label token in the warning colour. The drawing types
   it at 10px; arcade's label is 12 and that is the floor for a phone. */
.gs-sheet__note {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: var(--gs-type-label-text-transform, none);
  color: var(--gs-color-warning-solid);
}

/* The heading: the title token, in capitals, with the display shadow behind
   it. Arcade's title is Unbounded 20 at 900, which is what the drawing sets. */
.gs-sheet__label {
  margin-top: var(--gs-space-1);
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  text-transform: uppercase;
  text-shadow: var(--gs-type-display-shadow, none);
}

/* The line under it, in the secondary ink. Tom's floor: body is never under
   17px, so the drawing's 12px is not followed here. */
.gs-sheet__body {
  margin-top: var(--gs-space-2);
  color: var(--gs-color-ink-secondary);
}

/* -- the middle ------------------------------------------------------------ */
/* Whatever the host puts here: a list of options, a share row, filters. It is
   the one region that scrolls when the sheet is at its cap. */
.gs-sheet__content {
  min-height: 0;
  overflow: auto;
}

/* -- the actions ----------------------------------------------------------- */
.gs-sheet__actions {
  flex: none;
  display: grid;
  gap: var(--gs-space-2);
  margin-top: var(--gs-space-4);
}

.gs-sheet__actions > .gs-button {
  width: 100%;
}

/* The drawing paints the sheet's primary positive, the way the large game
   action is painted: it is the one thing the sheet is for. The library's
   primary is the interactive colour at this size, so the sheet sets the
   positive paint here, from the same two tokens the large action reads. */
.gs-sheet__actions > .gs-button[data-gs-variant='primary'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-positive);
  box-shadow: var(--gs-depth-pressable-positive);
}

.gs-sheet__actions > .gs-button[data-gs-variant='primary']:active:not([aria-disabled='true']) {
  box-shadow: var(--gs-depth-pressable-positive-pressed);
}

/**
 * The focus trap a sheet and a modal share.
 *
 * Both hold focus inside their panel while open, both close on Escape, and both
 * hand focus back to whatever had it when they opened. That is one behaviour,
 * so it is written once and each component calls it from an effect.
 *
 * It ships inside the `sheet` registry item, and `modal` depends on `sheet`
 * for it, the way `inventory` depends on `reward`: a customer installing a
 * modal should not have to know that a trap is a thing, and two copies of
 * forty lines would be two traps to keep the same.
 */

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'

export interface TrapOptions {
  /** The surface focus is held inside. */
  panel: HTMLElement
  /** What Escape does. A sheet dismisses; a modal takes its safe action. */
  onEscape: () => void
  /**
   * Where focus lands on open. A modal names its safe action so the dangerous
   * one is never the default; a sheet takes the first control it has, or the
   * panel itself when it has none.
   */
  initial?: HTMLElement | null
}

/**
 * Holds focus inside `panel` until the returned function is called, which is
 * the effect's cleanup. Focus goes back to the element that had it before.
 */
export function trapFocus({ panel, onEscape, initial }: TrapOptions): () => void {
  const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null
  const controls = () =>
    [...panel.querySelectorAll<HTMLElement>(FOCUSABLE)].filter((el) => el.closest('[hidden]') === null)

  // preventScroll, because a panel that opens at the foot of a scene must not
  // drag the page to it: the scene is what the player was looking at.
  const first = initial ?? controls()[0] ?? panel
  first.focus({ preventScroll: true })

  function onKeyDown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      // Claimed, because an open sheet or modal is the only thing Escape can
      // mean while it is open. This is the opposite of the coach mark rule,
      // and deliberately so: a modal is modal.
      event.preventDefault()
      event.stopPropagation()
      onEscape()
      return
    }
    if (event.key !== 'Tab') return
    const items = controls()
    const active = document.activeElement
    const inside = active instanceof HTMLElement && panel.contains(active)
    if (items.length === 0) {
      event.preventDefault()
      panel.focus({ preventScroll: true })
      return
    }
    const first = items[0]
    const last = items[items.length - 1]
    if (!first || !last) return
    if (event.shiftKey ? active === first || !inside : active === last || !inside) {
      event.preventDefault()
      ;(event.shiftKey ? last : first).focus({ preventScroll: true })
    }
  }

  document.addEventListener('keydown', onKeyDown, true)
  return () => {
    document.removeEventListener('keydown', onKeyDown, true)
    previous?.focus({ preventScroll: true })
  }
}
